(function (global) {
 const DB_NAME = 'faceRecoDB';
 const STORE_NAME = 'kv';

 function openIdb() {
 return new Promise((resolve, reject) => {
 const req = indexedDB.open(DB_NAME,1);
 req.onupgradeneeded = function () {
 const db = req.result;
 if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME);
 };
 req.onsuccess = function () { resolve(req.result); };
 req.onerror = function (e) { reject(req.error || e); };
 });
 }

 async function get(key) {
 try {
 const db = await openIdb();
 return await new Promise((resolve, reject) => {
 const tx = db.transaction(STORE_NAME, 'readonly');
 const store = tx.objectStore(STORE_NAME);
 const rq = store.get(key);
 rq.onsuccess = () => resolve(rq.result);
 rq.onerror = () => reject(rq.error);
 });
 } catch (e) {
 return null;
 }
 }

 async function set(key, value) {
 try {
 const db = await openIdb();
 return await new Promise((resolve, reject) => {
 const tx = db.transaction(STORE_NAME, 'readwrite');
 const store = tx.objectStore(STORE_NAME);
 const rq = store.put(value, key);
 rq.onsuccess = () => resolve(true);
 rq.onerror = () => reject(rq.error);
 });
 } catch (e) {
 return false;
 }
 }

 async function del(key) {
 try {
 const db = await openIdb();
 return await new Promise((resolve, reject) => {
 const tx = db.transaction(STORE_NAME, 'readwrite');
 const store = tx.objectStore(STORE_NAME);
 const rq = store.delete(key);
 rq.onsuccess = () => resolve(true);
 rq.onerror = () => reject(rq.error);
 });
 } catch (e) {
 return false;
 }
 }

 // Minimal idb-keyval compatible API
 const idbKeyval = {
 get: function (key) { return get(key); },
 set: function (key, value) { return set(key, value); },
 del: function (key) { return del(key); },
 clear: async function () {
 try {
 const db = await openIdb();
 return await new Promise((resolve, reject) => {
 const tx = db.transaction(STORE_NAME, 'readwrite');
 const store = tx.objectStore(STORE_NAME);
 const rq = store.clear();
 rq.onsuccess = () => resolve(true);
 rq.onerror = () => reject(rq.error);
 });
 } catch (e) { return false; }
 }
 };

 global.idbKeyval = idbKeyval;
 // Also expose shorthand names for compatibility
 global.idbKeyval_iife = idbKeyval;

})(this);
